 for(let r of awardDeadlines())if(r.left===0&&!s.awardReminders[r.key]){s.awardReminders[r.key]=true;log('Awards deadline this month',`${r.show.name}: ${r.count} eligible categories still have no submission. Entries are free. Open Awards before advancing.`)}
