function clearTourCities(){tourDraft.cities=[];(tourDraft.legs||[]).forEach(L=>L.cities=[]);tourPreview=null;say('All destinations cleared from your draft tour. Choose a new route.');}
function awardDeadlines(){return SHOWS.map(show=>{let at=ceremony(show),left=at-2-s.month,count=show.categories.filter(c=>eligible(show,c[1],at,c).length&&!s.awardEntries.some(e=>e.show===show.id&&e.at===at&&e.category===c[0])).length;return {show,at,left,count,key:show.id+'-'+at}}).filter(r=>r.count&&r.left>=0&&r.left<=2).sort((a,b)=>a.left-b.left)}
function openAwardReminder(id){awardPage='submit';awardShow=id;awardYear='all';show('awards')}
function careerNotices(){let labelOffers=(s.labelDesk?.offers||[]).filter(o=>o.status==='Open'&&o.expires>=s.month);let labelNote=tab!=='business'&&labelOffers.length?`<div class="notice row wrap"><span>${labelOffers.length} A&R offer(s) waiting in Record deals.</span><button onclick="show('business')">Review label offers</button></div>`:'';let reminders=awardDeadlines(),offers=s.pressDesk.offers.filter(o=>o.status==='Invited'&&o.expires>=s.month);return `${labelNote}${reminders.length?`<div class="notice"><b>Awards applications ${reminders[0].left===0?'due this month':'open'}</b>${reminders.map(r=>`<div class="row wrap"><span>${esc(r.show.name)} · ${r.count} unsubmitted categories · ${r.left===0?'Last chance before next month':MONTHS[(r.at-2)%12]+' '+year(r.at-2)+' deadline'}</span><button class="compact" onclick="openAwardReminder('${r.show.id}')">Submit work</button></div>`).join('')}</div>`:''}${tab!=='press'&&(offers.length||s.pressDesk.active)?`<div class="notice row wrap"><span>${s.pressDesk.active?'Your interview is in progress.':offers.length+' press invitation(s) waiting.'}</span><button class="compact" onclick="show('press')">Open press desk</button></div>`:''}`}
// Each work has a saved audience curve. Rendering never rerolls a chart run.
function audienceProfile(base,start,old=false){let kind=pick(['front','steady','grow','grow','sleeper']);return {base:Math.max(1,base),start,peak:old?rnd(0,3):kind==='front'?0:kind==='steady'?rnd(1,2):kind==='sleeper'?rnd(5,8):rnd(3,5),lift:kind==='front'?1:kind==='steady'?rnd(115,155)/100:rnd(175,350)/100,decay:rnd(76,94)/100,phase:Math.random()*6.28,boost:0,boostLeft:0,lastMonth:start}}
function prepareDebutAudience(a){let singles=a.tracks.filter(t=>t.single),weights=singles.map(t=>rnd(40,160)*(a.tracks[a.lead]===t?1.12:1)),sum=weights.reduce((n,v)=>n+v,0);singles.forEach((t,i)=>{t.firstStreams=Math.round(a.streams*.72*weights[i]/sum);t.total=t.firstStreams;t.audience=audienceProfile(t.firstStreams,s.month)});a.audience=audienceProfile(Math.max(1,a.streams-singles.reduce((n,t)=>n+t.firstStreams,0)),s.month)}
function ensureAudience(a){
 for(let t of a.tracks)if(t.single&&!t.audience){let p=t.chartHistory?.at(-1),elapsed=Math.max(0,s.month-(t.released??a.month));t.audience=audienceProfile(p?.streams??(elapsed?Math.max(1,t.firstStreams*.22*Math.pow(.92,elapsed-1)):t.firstStreams),s.month,elapsed>0)}
 if(!a.audience){let p=a.chartHistory?.at(-1),elapsed=s.month-a.month,current=p?.streams??(elapsed?Math.max(1,a.streams*.26*Math.pow(.93,elapsed-1)):a.streams),songs=a.tracks.filter(t=>t.single).reduce((n,t)=>n+t.audience.base,0);a.audience=audienceProfile(Math.max(current*.18,current-songs),s.month,elapsed>0)}
}
function audienceMonth(p,quality,video=false){let m=Math.max(0,s.month-p.start),ramp=p.peak===0?1:1+(p.lift-1)*Math.pow(Math.min(1,m/p.peak),1.25),fade=m>p.peak?Math.pow(p.decay,m-p.peak):1,noise=1+.09*Math.sin(m*1.7+p.phase)+rnd(-7,7)/100,boost=p.boostLeft>0?p.boost:0;
 if(p.boostLeft>0){p.boostLeft--;p.boost*=.72}let n=Math.round(Math.min(40000000,p.base*ramp*fade*noise*(1+boost)*(video?1.1:1)));p.lastMonth=s.month;return Math.max(0,n)}
function advanceAudience(a){ensureAudience(a);let eraBoost=a.audience.boostLeft>0?a.audience.boost:0,deep=albumChartEligible(a)?Math.round(audienceMonth(a.audience,a.quality)*careerMultiplier('audience')):0,songTotal=0;for(let t of a.tracks)if(t.single){let n=Math.round(audienceMonth(t.audience,t.quality,false)*videoReach(t)*(1+eraBoost)*(1+Math.min(.12,t.creditLift||0)*Math.max(0,1-(s.month-t.released)/6))*careerMultiplier('audience'));if(typeof digitalListening==='function')n=digitalListening(a,t,n);t.total+=n;songTotal+=n;putChartPoint(t,(t.chartHistory.find(p=>p.month===s.month)?.streams||0)+n)}let promotion=monthlyLabelPromotion(a);let collection=trackCollectionStreams(a,deep+promotion);return (collection??deep+promotion)+songTotal}
function boostWork(a,t,amount){if(!a)return;ensureAudience(a);let p=(t||a).audience;if(!p)return;p.boost=Math.min(1.5,(p.boost||0)+amount);p.boostLeft=Math.max(p.boostLeft||0,3)}
