function spending(){let works=s.albums.flatMap(a=>[{id:a.id,title:a.title+' · '+(published(a)?releaseLabel(a):'upcoming project')},...a.tracks.filter(t=>t.single).map(t=>({id:t.id,title:t.title+' · single'}))]);$('view').innerHTML=`<div class="card"><div class="eyebrow">LIFESTYLE & INVESTMENTS</div><h2>What will your music make possible?</h2><p class="muted">Build your creative space, fund a campaign, or enjoy the life around the music. Every purchase costs one action. Equipment and existing treats keep their original costs. New housing and lifestyle items show their recurring costs before confirmation.</p><p>Available: <b>${cashExact(s.cash)}</b></p><label>Campaign target<select id="spendTarget">${works.map(w=>`<option value="${w.id}">${esc(w.title)}</option>`).join('')||'<option>No released music yet</option>'}</select></label></div>${[...new Set(INVESTMENTS.map(x=>x[3]))].map(group=>`<div class="card"><h3>${group}</h3><div class="grid">${INVESTMENTS.filter(x=>x[3]===group).map(([id,name,cost,g,desc,frequency])=>{let bought=s.investments[id],locked=frequency==='once'?!!bought:s.purchases.some(p=>p.id===id&&p.month===s.month);return `<button class="choice" onclick="buyInvestment('${id}')" ${locked||s.retired||s.ap<1||s.cash<cost||id==='house'&&age()<18||LIFESTYLE_ITEMS[id]&&age()<LIFESTYLE_ITEMS[id].age||g==='Campaigns'&&!works.length?'disabled':''}><strong>${name} · ${cashExact(cost)}</strong><small>${desc}</small><small>${locked?(frequency==='once'?'Purchased':'Purchased this month'):'1 action'}</small></button>`}).join('')}</div></div>`).join('')}<div class="card"><h3>Purchase history</h3>${s.purchases.length?`<div class="scroll"><table><tr><th>Date</th><th>Purchase</th><th>Paid</th></tr>${s.purchases.slice(0,30).map(p=>`<tr><td>${MONTHS[p.month%12]} ${year(p.month)}</td><td>${esc(p.name)}${p.target?'<br><small>'+esc(p.target)+'</small>':''}</td><td>${cashExact(p.cost)}</td></tr>`).join('')}</table></div>`:'<p class="muted">Your investments and treats will appear here.</p>'}</div>`}
function buyInvestment(id){let item=INVESTMENTS.find(x=>x[0]===id);if(!item)return;let [,name,cost,group,,freq,v]=item;if(freq==='once'&&s.investments[id]||freq==='monthly'&&s.purchases.some(p=>p.id===id&&p.month===s.month)||id==='house'&&age()<18)return;let a,t;if(group==='Campaigns'){let target=$('spendTarget').value;a=s.albums.find(a=>a.id===target||a.tracks.some(t=>t.id===target&&t.single));t=a?.tracks.find(t=>t.id===target);if(!a)return say('Release music before buying a campaign.')}let apCost=id==='holiday'?WEEK_BREAK_ACTIONS:1;if(s.ap<apCost)return say(`This uses ${apCost} actions and you have ${s.ap} left this week.`);if(!canAct(cost,0))return;s.ap-=apCost;change({...v,cash:-cost});s.investments[id]={month:s.month};if(a)boostWork(a,t,id==='photos'?.12:id==='radio'?.25:.45);s.purchases.unshift({id,name,cost,month:s.month,target:a?(t||a).title:null});log(name,`${cashExact(cost)} spent. ${item[4]}`);say(`${name} purchased for ${cashExact(cost)}.`)}
function equipmentBonus(k){if(k==='write')change({prep:careerEffectValue('writing')});if(k==='write')change({prep:s.investments.mic?3:0,craft:s.investments.keys?1:0});if(k==='produce'&&s.investments.studio)change({prep:5})}
